						short: "The sextile is often read quite like a trine, although there is a distinction between the two aspects. Sextiles, like trines, point to some talent and ease. However, sextiles have a little more \"oomph\" to them. While trines come so naturally to people that they might have to be reminded of their own talents or tendencies, sextiles are a little more overt to the native. These are the talents that people appreciate in themselves. They may be more inclined to notice and work on these talents.",
