				description: "Vyaya means expenditure and this house represents our expenses. The twelfth house is also a house of endings and can bring a sense of loss and sorrow. However this house is also powerful spiritually and is where we find liberation and enlightenment. In the twelfth house we give up our sense of ego in order to merge with a universal and eternal consciousness. The energy moves inward in the twelfth house, and there can be a need for seclusion, meditation and contemplation. This house represents places that are worlds unto themselves, somewhat separate from society. These can include retreats, monasteries and places where people heal themselves, such as hospitals or even prisons. Through this house we can also experience a sense of confinement, isolation and loneliness. The twelfth house can give us the urge to travel to distant locations. There is often a desire to explore the unknown and the foreign. This house governs the subtle energies we feel but do not always understand. Vyaya Bhava governs clairvoyance, healing, sleep and dreams. Intuition and imagination are strong in the twelfth house, and we often find writers, thinkers, actors and clairvoyants having planets in this house. The twelfth house can also manifest careers involving institutions, organizations, charity and healing. People with planets in the twelfth house can be empathic and they often express a great deal of compassion and generosity towards others.",
