		strengths: [
			"You're the most courageous and ambitious sign, the leader of every pack.",
			"Your determination is unmatched when it comes to getting what you want.",
			"You work hard but also play hard, and you're the life of every party!",
			"You're easygoing and enjoy the company of all kinds of people.",
			"You're impulsive. Sure, sometimes acting first and thinking later is risky, but more often than not, it leads to a once-in-a-lifetime opportunity.",
		],
		motto: "\"When you know yourself, you're empowered. When you accept yourself, you're invincible.\"",
		gifts: "Whether it's backpacking around the world, launching a business, or training for a marathon, once an Aries sets a goal, they will achieve it. They don't care what anyone else thinks, and can tune into their intuition and dreams in a heartbeat. Rams never need a plus one: they love their own company, and consider going solo to the movies a rare treat.",
		challenges: "The world according to an Aries makes so much sense that they have a hard time listening to, much less accepting, alternative viewpoints. Slowing down is also tough. A Ram's mind goes a million miles a minute, and slowing down for others can be excruciating. But when it comes to maintaining relationships, Aries must learn to adapt and embrace other ways of doing, being, and seeing.",
		weapon: "Strong, adamant, and forged in fire, it's fitting that Aries' secret weapon is iron, one of the strongest elements. Weld, cast, machine, forge, temper, harden, or anneal it, iron can take on a seemingly limitless range of shapes and qualities. For an Aries, an iron-rich diet can boost confidence and performance.",
		compatibleSigns: [
			"Leo",
			"Sagittarius",
			"Gemini",
		],
