	hex: {
		number: 16,
		symbol: "䷏",
		chinese: "豫",
		english: "Enthusiasm",
		pinyin: "Yù",
		binary: "000100",
		upperTrigram: "Thunder",
		lowerTrigram: "Earth",
		judgment: "Something has caught, and the energy released is enough to install leaders and to set armies moving. Enthusiasm is a resource in this situation, so give it a form and a direction before it burns itself out.",
		image: "Thunder breaks out of the earth and the ground itself resounds. Give collective feeling something to run through: honour what has genuinely been achieved, and let the celebration carry a real meaning.",
		interpretation: {
			general: "Enthusiasm and inspiration are stirring. This is the right time to set things in motion, rally support, and begin new initiatives. Like thunder breaking from the earth, energy wants to move. Channel this enthusiasm wisely through proper planning and inspired action.",
			love: "Shared enthusiasm brings joy to relationships. Find what inspires both of you and pursue it together. Positive energy attracts positive connections.",
			career: "Inspire others through your vision and energy. The time is right for rallying support around your ideas. Enthusiasm properly channeled moves people to action.",
			decision: "Act with enthusiasm and confidence. This is a favorable time to move forward with plans that inspire you. Let your energy set the tone.",
			advice: "When thunder rises from the earth, all things respond with enthusiasm. Use this energy to set things in motion. Proper timing and inspiration together create momentum.",
		},
		changingLines: [
			{
				position: 1,
				text: "Trumpeting your own enthusiasm brings misfortune.",
				meaning: "The first place is the beginning, and this yin line sits at the bottom of the situation with a powerful connection above it that it did nothing to earn. Announcing that connection converts it into a liability. Say nothing about who you are close to, because boasting from a low position is what gets the connection taken away.",
			},
			{
				position: 2,
				text: "Firm as a rock, and not waiting even a full day.",
				meaning: "The second place is inner and central, and this yin line is the only one in the hexagram that is not swept along by the mood. It sees where the enthusiasm is heading before the enthusiasm gets there, and it moves at once. Stay clear headed inside the excitement and act on what you see the moment you see it.",
			},
			{
				position: 3,
				text: "Staring up at the one above and enjoying yourself, and every day of hesitation adds to the regret.",
				meaning: "The third place is the exposed threshold, and this yin line has attached itself to the source of the excitement and is coasting on it. Living on the energy of another person is not a position, it is a postponement. Change course now, because the regret grows with every day it is delayed.",
			},
			{
				position: 4,
				text: "You are the source the enthusiasm comes from; do not doubt it, and friends gather the way hair gathers into a clasp.",
				meaning: "The fourth place is next to authority, and this single yang line actually generates the movement everyone else is riding. Its one real danger is self suspicion. Trust what you are doing and hold the center of it, and people will assemble around you without being asked.",
			},
			{
				position: 5,
				text: "A chronic complaint that never quite kills you.",
				meaning: "This is the ruling line, and a yin line in the place of authority is weak, hemmed in by the strong line just beneath it, and unable to enjoy any of what is happening. The affliction is also a protection, since it prevents the collapse into pleasure that would finish the position off. Accept the constraint, stay alive inside it, and do not compete for energy that belongs to someone else.",
			},
			{
				position: 6,
				text: "The enthusiasm has gone blind, and even now a change of course leaves you without fault.",
				meaning: "The sixth place is past the peak, and this yin line has stayed with the excitement long after it stopped meaning anything. Nothing is at stake here except the willingness to admit that. Turn away from what is finished, and the error ends with the turning.",
			},
		],
	},
